<template>
 <div class="exchange-returns" v-loading="loading || busy">
  <div class="section-title"><div><h3>退回与验收</h3><p class="muted">寄回物流、仓库实收、库存记账和人工验收分别记录。</p></div><el-button size="small" @click="load">刷新退回明细</el-button></div>
  <el-alert v-if="error" :title="error" type="error" :closable="false" />
  <el-alert v-if="!required" title="未发货替换无需买家退回，也无需退回验收。" type="info" :closable="false" />
  <template v-else>
   <div class="return-metrics"><div><span>应退</span><b>{{ exchange.requested_quantity }}</b></div><div><span>仓库实收</span><b>{{ metric('accepted_quantity') }}</b></div><div><span>良品 / 次品</span><b>{{ grades ? grades.good_qty + ' / ' + grades.bad_qty : '—' }}</b></div><div><span>已入账</span><b>{{ metric('posted_quantity') }}</b></div><div><span>待退</span><b>{{ actual ? Math.max(0, Number(exchange.requested_quantity) - Number(actual.accepted_quantity)) : '—' }}</b></div><div><span>人工验收</span><b class="small-value">{{ ({PASSED:'已确认', ISSUE:'差异待处理'})[exchange.return_qc] || '待验收' }}</b></div></div>
   <el-descriptions border :column="2" size="small"><el-descriptions-item label="原商品 / 应退数量">{{ exchange.original_sku }} / {{ exchange.requested_quantity }} 件</el-descriptions-item><el-descriptions-item label="来源发货明细">#{{ exchange.source_shipment_line_id || '待选择' }}</el-descriptions-item><el-descriptions-item label="审核退回仓">{{ exchange.return_store || '待审核确认' }}<div class="muted">各次退回仓与寄回地址请在“退回单”查看。</div></el-descriptions-item><el-descriptions-item label="最近退回入库单"><router-link v-if="exchange.return_sn" :to="{ path:'/oms-supplychain/wmsTickets', query:{ sn:exchange.return_sn, documentId:actual && actual.ticket_id || undefined } }">{{ exchange.return_sn }}</router-link><span v-else>尚未生成</span></el-descriptions-item><el-descriptions-item label="审核寄回地址">{{ plan.return_address || '请按已核对的退回地址寄回' }}<div class="muted">{{ plan.return_contact || '' }}<span v-if="exchange.platform_address_id"> · 平台退货地址 ID {{ exchange.platform_address_id }}</span></div></el-descriptions-item><el-descriptions-item label="仓库受理 / 收货">{{ actual ? dispatchLabel(actual.dispatch_state) + ' / ' + receiptLabel(actual.receipt_state) : exchange.return_sn ? '明细尚未加载' : '待生成退回单' }}</el-descriptions-item></el-descriptions>
   <section class="return-section"><div class="section-title"><h3>买家寄回物流</h3><el-button v-if="editable" v-hasPermi="['order:exchange:execute']" size="small" :disabled="!!error || loading" @click="editLogistics">登记 / 修改物流</el-button></div><p class="muted">登记运单不代表仓库已收货，不增加库存。平台同步和客服登记分别标识。</p><el-table :data="tracks" empty-text="尚无寄回物流"><el-table-column label="承运商" prop="carrier" /><el-table-column label="寄回运单号" prop="tracking_no" min-width="200" /><el-table-column label="寄回时间" prop="shipped_at" min-width="165" /><el-table-column label="来源" width="120"><template slot-scope="s">{{ s.row.source === 'PLATFORM' ? '平台同步' : '客服登记' }}</template></el-table-column><el-table-column label="备注" prop="note" min-width="180" /></el-table></section>
   <section class="return-section"><div class="section-title"><h3>仓库实收与库存记账</h3><div v-if="editable && exchange.return_sn"><el-button v-hasPermi="['order:exchange:execute']" size="small" @click="warehouseAction('query')">查询仓库原单</el-button><el-button v-if="actual && actual.dispatch_state === 'FAILED'" v-hasPermi="['order:exchange:execute']" size="small" @click="warehouseAction('retry')">重试明确失败的下发</el-button><el-button v-if="actual && actual.last_error && Number(actual.accepted_quantity) > Number(actual.posted_quantity)" v-hasPermi="['order:exchange:execute']" size="small" @click="warehouseAction('posting')">重试原回执记账</el-button></div></div><el-alert v-if="actual && actual.last_error" :title="actual.last_error" type="warning" :closable="false" /><el-table :data="actual && actual.lines || []" empty-text="暂无已接收的实收明细"><el-table-column label="退回单" prop="return_sn" min-width="270" /><el-table-column label="回传时间" prop="create_time" min-width="165" /><el-table-column label="SKU / 批次" min-width="230"><template slot-scope="s">{{ s.row.sku_sn }}<div class="muted">{{ s.row.batch_code }}</div></template></el-table-column><el-table-column label="良品 / 次品" width="120"><template slot-scope="s">{{ s.row.good_qty }} / {{ s.row.bad_qty }}</template></el-table-column><el-table-column label="记账结果" width="110"><template slot-scope="s"><el-tag size="mini" :type="Number(s.row.posted) ? 'success' : 'warning'">{{ Number(s.row.posted) ? '已入账' : '待入账' }}</el-tag></template></el-table-column><el-table-column label="回传标识" prop="message_id" min-width="210" /></el-table>
    <template v-if="actual && (actual.rejected_receipts || []).length"><h4>被拒绝的回传 · 待核对</h4><p class="muted">以下回传未形成有效实收或新增库存。核对后由仓库更正事实并回传，保留原拒绝记录。</p><el-table :data="actual.rejected_receipts"><el-table-column label="时间" prop="create_time" min-width="165" /><el-table-column label="原因" prop="error_info" min-width="280" /></el-table></template><router-link v-if="exchange.return_sn" :to="{path:'/oms-supplychain/wmsLogs',query:{numberType:'DOCUMENT',number:exchange.return_sn,allTime:'true'}}">查看完整仓库交互日志</router-link></section>
   <section class="return-section"><div class="section-title"><h3>验收与差异处理</h3><el-button v-if="editable && !exchange.fulfillment_line_id && actual && exchange.platform_operation === 'NONE'" v-hasPermi="['order:exchange:execute']" type="primary" size="small" @click="openReview">{{ exchange.return_qc === 'ISSUE' ? '处理退回差异' : '登记验收结果' }}</el-button></div><el-alert v-if="exchange.return_qc === 'ISSUE'" title="退回差异尚未解决，暂缓换出。" type="warning" :closable="false" /><el-descriptions v-if="report.review && report.review.decision" border :column="2" size="small"><el-descriptions-item label="处理结论">{{ decisions[report.review.decision] || report.review.decision }}</el-descriptions-item><el-descriptions-item label="差异类型">{{ issues[report.review.issue_type] || '无' }}</el-descriptions-item><el-descriptions-item label="处理依据">{{ report.review.reason }}</el-descriptions-item><el-descriptions-item label="凭证 / 协商记录">{{ report.review.evidence || '未填写' }}</el-descriptions-item><el-descriptions-item label="处理人 / 时间">{{ report.review.actor }} / {{ report.review.at }}</el-descriptions-item></el-descriptions><p v-else class="muted">{{ exchange.return_qc_reason || '等待仓库实收及人工验收。少退可登记等待补退；差异处理不会修改实收数量。' }}</p></section>
  </template>
  <el-dialog title="登记买家寄回物流" :visible.sync="logisticsVisible" width="min(900px, 96vw)" append-to-body :close-on-click-modal="false"><el-alert title="客服登记仅作跟踪，不代替仓库实收回传。" type="info" :closable="false" /><div v-for="(item,i) in items" :key="i" class="track-editor"><el-input v-model.trim="item.carrier" placeholder="承运商" maxlength="100" /><el-input v-model.trim="item.tracking_no" placeholder="寄回运单号" maxlength="100" /><el-date-picker v-model="item.shipped_at" type="datetime" value-format="yyyy-MM-dd HH:mm:ss" placeholder="寄回时间（选填）" /><el-input v-model="item.note" placeholder="备注" maxlength="500" /><el-button type="text" @click="items.splice(i,1)">移除</el-button></div><el-button :disabled="items.length >= 20" size="small" @click="items.push({carrier:'',tracking_no:'',shipped_at:'',note:''})">添加寄回运单</el-button><span slot="footer"><el-button @click="logisticsVisible=false">取消</el-button><el-button type="primary" :loading="busy" @click="saveLogistics">保存物流记录</el-button></span></el-dialog>
  <el-dialog title="退回验收与差异处理" :visible.sync="reviewVisible" width="min(660px,96vw)" append-to-body :close-on-click-modal="false"><el-alert title="库存由有效仓库实收回传记账；本次只记录验收结论，不增减库存。" type="info" :closable="false" /><el-form label-width="110px" class="review-editor"><el-form-item label="处理动作"><el-select v-model="review.decision"><el-option v-for="(name,key) in decisions" :key="key" :value="key" :label="name" :disabled="['PASSED','ALLOW_EXCHANGE'].includes(key) && !full || key === 'PASSED' && exchange.return_qc === 'ISSUE'" /></el-select></el-form-item><el-form-item label="差异类型"><el-select v-model="review.issue_type" clearable><el-option v-for="(name,key) in issues" :key="key" :value="key" :label="name" /></el-select></el-form-item><el-form-item label="处理依据"><el-input v-model="review.reason" type="textarea" maxlength="500" show-word-limit /></el-form-item><el-form-item label="凭证 / 协商记录"><el-input v-model="review.evidence" type="textarea" maxlength="2000" show-word-limit placeholder="填写工单号、凭证地址或协商记录引用" /></el-form-item></el-form><span slot="footer"><el-button @click="reviewVisible=false">取消</el-button><el-button type="primary" :loading="busy" @click="saveReview">保存验收处理</el-button></span></el-dialog>
 </div>
</template>
<script>
import { exchangeReturnReport, exchangeAction } from '@/api/order/exchange'
import { unshipped, ended } from './exchangePresentation'
export default {
 props:{exchange:{type:Object,required:true}},
 data(){return {loading:false,busy:false,error:'',report:{},sequence:0,logisticsVisible:false,reviewVisible:false,items:[],review:{},decisions:{PASSED:'正常验收通过',ALLOW_EXCHANGE:'差异核对后继续换货',WAIT_SUPPLEMENT:'等待买家补退',WAREHOUSE_REVIEW:'登记待仓库复核',BUYER_CONTACT:'联系买家协商',HOLD:'暂缓换出'},issues:{SHORT:'少退',EXCESS:'多退',WRONG_ITEM:'错货',DAMAGED:'破损 / 次品',MISSING_PARTS:'配件缺失',POSTING:'记账待核对'}}},
 computed:{required(){return !unshipped(this.exchange)},editable(){return !ended(this.exchange)&&!this.exchange.linked_exchange_id},actual(){return !this.error&&this.report.actual||null},grades(){return this.actual&&this.actual.grades},plan(){return this.exchange.approved_snapshot||{}},full(){return this.actual&&this.actual.receipt_state==='COMPLETED'&&Number(this.actual.posted_quantity)===Number(this.exchange.requested_quantity)},tracks(){const rows=[...(this.report.logistics||[])];const p=this.report.platform_logistics||{};if(p.tracking_no)rows.unshift({...p,source:'PLATFORM'});return rows}},
 watch:{'exchange.control_version'(){this.load()}},created(){this.load()},beforeDestroy(){this.sequence++},
 methods:{metric(key){return this.actual?this.actual[key]:'—'},dispatchLabel(s){return ({PENDING:'待下发',SENDING:'下发中',UNKNOWN:'结果待确认',ACCEPTED:'仓库已接收',FAILED:'下发失败'})[s]||s},receiptLabel(s){return ({WAITING:'待收货',PARTIAL:'部分收货',POSTING:'记账中',POSTING_FINAL:'最终回执记账中',COMPLETED:'收货已完成'})[s]||s},
 async load(){const seq=++this.sequence;this.loading=true;this.error='';try{const r=await exchangeReturnReport(this.exchange.id);if(seq===this.sequence)this.report=r.data}catch(_){if(seq===this.sequence)this.error='退回明细加载失败，请刷新；未将未知数量当作零。'}finally{if(seq===this.sequence)this.loading=false}},
 editLogistics(){this.items=(this.report.logistics||[]).map(x=>({...x}));if(!this.items.length)this.items.push({carrier:'',tracking_no:'',shipped_at:'',note:''});this.logisticsVisible=true},
 async command(action,body){if(this.busy)return;this.busy=true;try{await exchangeAction(this.exchange.id,action,{...body,control_version:this.exchange.control_version});this.logisticsVisible=false;this.reviewVisible=false;this.$emit('changed');this.$message.success('处理记录已保存')}finally{this.busy=false}},
 saveLogistics(){if(this.items.some(x=>!x.carrier.trim()||!x.tracking_no.trim()))return this.$message.warning('请填写每条物流的承运商和运单号');return this.command('return-logistics',{items:this.items})},
 openReview(){this.review={decision:this.full?(this.exchange.return_qc==='ISSUE'?'ALLOW_EXCHANGE':'PASSED'):'WAIT_SUPPLEMENT',issue_type:this.full?'':'SHORT',reason:'',evidence:''};this.reviewVisible=true},
 saveReview(){if(!(this.review.reason||'').trim())return this.$message.warning('请填写处理依据');if(!['PASSED','ALLOW_EXCHANGE'].includes(this.review.decision)&&!this.review.issue_type)return this.$message.warning('请选择差异类型');return this.command('qc',this.review)},warehouseAction(action){return this.command('return/'+action,{})}
 }
}
</script>
<style scoped>
.exchange-returns{color:#42566e}.section-title{display:flex;justify-content:space-between;align-items:center;gap:14px;flex-wrap:wrap;margin:18px 0 12px}.section-title h3{font-size:16px;margin:0}.muted{font-size:12px;line-height:1.8;color:#8490a2}.return-metrics{display:flex;flex-wrap:wrap;justify-content:space-between;gap:16px;padding:20px;background:#f3f7fd;border-radius:8px;margin:16px 0}.return-metrics span{font-size:12px;color:#7e8b9c}.return-metrics b{display:block;margin-top:8px;font-size:23px}.return-metrics b.small-value{font-size:15px}.return-section{padding:10px 0 20px;border-bottom:1px solid #e5ebf3}.return-section>a{display:inline-block;margin-top:14px;color:#1683e5;font-size:13px}.track-editor{display:grid;grid-template-columns:100px 1fr 190px 1fr 45px;gap:8px;margin:14px 0;align-items:center}.track-editor .el-date-editor{width:100%}.review-editor{margin-top:20px}.review-editor .el-select{width:100%}
</style>
